#include <iostream>
#include <climits>
using namespace std;


class Solution {
public:
    int prevVal = -1;
    int minDiff = INT_MAX;

    int minDiffInBST(TreeNode* root) {
        if (!root) return minDiff;
        minDiffInBST(root->left);
        if (prevVal != -1) {
            minDiff = min(minDiff, root->val - prevVal);
        }
        prevVal = root->val;
        minDiffInBST(root->right);
        return minDiff;
    }
};
